def copy_session_mode_to_opening_device(apps, schema_editor):
    """El modo de cada sesión existente pasa a ser el del dispositivo que la abrió."""
    POSSession = apps.get_model('treasury', 'POSSession')
    POSSessionDevice = apps.get_model('treasury', 'POSSessionDevice')
    POSSessionDevice.objects.bulk_create([
        POSSessionDevice(session_id=s.pk, user_id=s.user_id, mode=s.mode)
        for s in POSSession.objects.all().only('pk', 'user_id', 'mode')
    ])


def restore_session_mode_from_opening_device(apps, schema_editor):
    POSSession = apps.get_model('treasury', 'POSSession')
    POSSessionDevice = apps.get_model('treasury', 'POSSessionDevice')
    for device in POSSessionDevice.objects.filter(mode='MULTI'):
        POSSession.objects.filter(pk=device.session_id, user_id=device.user_id).update(mode='MULTI')


